template<class T> struct is_reference : std::false_type {};
template<class T> struct is_reference<T&> : std::true_type {};
template<class T> struct is_reference<T&&> : std::true_type {};

examples.code:
#include <iostream>
#include <type_traits>

class A {};

int main() {
#define REF(x) << #x " ?: " << x << '\n'
    std::cout << std::boolalpha REF(std::is_reference_v<A>)
            REF(std::is_reference_v<A &>) REF(std::is_reference_v<A &&>)
                REF(std::is_reference_v<long>) REF(std::is_reference_v<long &>)
                    REF(std::is_reference_v<long &&>) REF(std::is_reference_v<double *>)
                        REF(std::is_reference_v<double *&>)
                            REF(std::is_reference_v<double *&&>);
#undef REF
}
